// Get all incoming items
const allItems = $input.all();

// Separate config items
const configItems = allItems.filter(
  i => i.json && i.json.config_key && i.json.config_value
);

function safe(s) {
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/'/g, '&#39;')
    .replace(/"/g, '&quot;');
}

// Extract config values
const config = {
  dev_server: configItems.find(i => i.json.config_key === 'selected_dev_server_name')?.json.config_value,
  prod_server: configItems.find(i => i.json.config_key === 'selected_prod_server_name')?.json.config_value
};

// Relative webhook URL (CORRECT)
const postUrl = "/webhook/admin-config-step2";

// Build HTML
const html = `
<!DOCTYPE html>
<html>
<head>
  <title>Admin Config: Step 1</title>
  <style>
    body { font-family: Arial; padding: 40px; }
    .container { max-width: 600px; margin: auto; }
    label { display: block; margin-top: 15px; }
    input { width: 100%; padding: 8px; margin-top: 5px; }
    button { margin-top: 25px; padding: 10px 15px; }
  </style>
</head>
<body>
<div class="container">
  <h1>Step 1: Set Server Connections</h1>

  <form action="${postUrl}" method="POST">
    <h3>Development</h3>
    <label>Development Server Name</label>
    <input type="text" name="dev_server"
      value="${safe(config.dev_server || '')}" required>

    <h3>Production</h3>
    <label>Production Server Name</label>
    <input type="text" name="prod_server"
      value="${safe(config.prod_server || '')}" required>

    <button type="submit">Next: Select Databases</button>
  </form>
</div>
</body>
</html>
`;

// IMPORTANT: must return array
return [
  {
    json: {
      htmlResponse: html
    }
  }
];

const mssql = require('mssql');

// *** ENTER YOUR SHARED CREDENTIALS HERE ***
const SHARED_USER = "sa";
const SHARED_PASSWORD = "dot@123";
// *******************************************

// Get the first input item (from the webhook)
const inputData = $input.all()[0].json.body;
const devServer = inputData.dev_server;

const config = {
    user: SHARED_USER, 
    password: SHARED_PASSWORD, 
    server: devServer, 
    pool: { max: 5, min: 0, idleTimeoutMillis: 30000 },
    options: { 
        encrypt: true, 
        trustServerCertificate: true 
    }
};

const query = "SELECT name FROM sys.databases WHERE database_id > 4 AND state = 0 ORDER BY name;";

try {
    const pool = new mssql.ConnectionPool(config);
    await pool.connect(); 
    const result = await pool.query(query);
    await pool.close(); 

    // Return an array of n8n items
    return result.recordset.map(item => ({ json: { db_name: item.name, type: 'dev' } }));

} catch (err) {
    // Also return an array
    return [{ json: { error: `Failed to connect to Dev Server (${devServer}): ${err.message}` } }];
}

// Always read ONLY from input
const input = $input.first().json;

const devServer = input.dev_server;
const prodServer = input.prod_server;
const devDatabases = input.dev_databases || [];
const prodDatabases = input.prod_databases || [];

// Build options
const devDbOptions = devDatabases
  .map(db => `<option value="${db}">${db}</option>`)
  .join('');

const prodDbOptions = prodDatabases
  .map(db => `<option value="${db}">${db}</option>`)
  .join('');

const html = `
<!DOCTYPE html>
<html>
<head>
  <title>Step 2: Select Databases</title>
  <style>
    body { font-family: Arial; padding: 40px; }
    select { width: 300px; padding: 6px; }
    button { margin-top: 20px; padding: 8px 16px; }
  </style>
</head>
<body>

<h2>Step 2: Select Databases</h2>

<form method="POST" action="/webhook/admin-config-save">

<h3>Development</h3>
<p>Server: <b>${devServer}</b></p>
<input type="hidden" name="dev_server" value="${devServer}">
<select name="dev_database">
  ${devDbOptions}
</select>

<h3>Production</h3>
<p>Server: <b>${prodServer}</b></p>
<input type="hidden" name="prod_server" value="${prodServer}">
<select name="prod_database">
  ${prodDbOptions}
</select>

<br/>
<button type="submit">Save Configuration</button>

</form>

</body>
</html>
`;

return [{ json: { htmlResponse: html } }];

