// Function node: Build SQL Credentials
const items = [];

for (const item of $input.all()) {
  const json = item.json;

  // Build connection string
  const connectionString = `Server=${json.server};Database=${json.database};User Id=${json.username};Password=${json.password};`;

  // Alternative: Build credential object
  const credentials = {
    server: json.server,
    database: json.database,
    username: json.username,
    password: json.password,
    port: json.port || 1533,
    connectionString: connectionString
  };

  items.push({
    json: {
      ...json,
      sqlCredentials: credentials,
      connectionString: connectionString
    }
  });
}

return items;

