// Read webhook
const body = $items("Webhook3")[0].json.body;
const prodServer = body.prod_server;

if (!prodServer) {
  return [{ json: { error: "prod_server missing from webhook" } }];
}

// Read merged rows
const rows = $items("Merge2")[0].json.rows;

const norm = v => String(v).trim().toLowerCase();

const match = rows.find(
  r => norm(r.ServerName) === norm(prodServer)
);

if (!match) {
  return [{
    json: {
      error: "No matching server found",
      prodServer,
      availableServers: rows.map(r => r.ServerName)
    }
  }];
}

// OUTPUT ONE ITEM ONLY
return [{
  json: {
    host: match.ServerName,
    // FIX 2: Force port to be a Number using parseInt or Number()
    port: Number(match.Port || 1433),
    // FIX 1: Keep the trim() we added earlier
    user: String(match.UserName).trim(),
    password: String(match.Password).trim()
  }
}];

// 1. Get the target server name from the Webhook node
// We look back to "Webhook3" to see what server was requested
const webhookItems = $items("Webhook3");

if (!webhookItems.length || !webhookItems[0].json.body) {
   throw new Error("Could not find Webhook3 data. Make sure the workflow started from the webhook.");
}

const targetServer = webhookItems[0].json.body.prod_server;

// 2. Get the list of credentials from the current input
// The "Extract from File" node outputs a list of items, so we use $input.all()
const allCredentials = $input.all();

// Helper function to clean text (removes spaces and makes lowercase)
const normalize = (str) => String(str || '').trim().toLowerCase();
const targetNorm = normalize(targetServer);

// 3. Find the matching server
// We look through all items from the Excel file to find the matching ServerName
const match = allCredentials.find(item => 
  normalize(item.json.ServerName) === targetNorm
);

if (!match) {
  const available = allCredentials.map(i => i.json.ServerName).join(', ');
  throw new Error(`Server '${targetServer}' not found in the credentials file. Available: ${available}`);
}

const data = match.json;

// 4. Output the single clean credential object
return [{
  json: {
    host: data.ServerName,
    // FIX: Force port to be a Number (Integer)
    port: parseInt(data.Port || 1433, 10),
    // FIX: Remove hidden "New Lines" (\n) or spaces from user/password
    user: String(data.UserName).trim(),
    password: String(data.Password).trim()
  }
}];

// Collect database names from all incoming items
const dbs = $input.all().map(i => i.json.name);

// Get server names from ANY previous node (Webhook / config merge)
const prev = $items("Webhook3")[0].json.body;

return [{
  json: {
    dev_server: prev.dev_server,
    prod_server: prev.prod_server,
    databases: dbs
  }
}];

const items = $input.all();

// holders
let devServer = '';
let prodServer = '';

const devDatabases = [];
const prodDatabases = [];

// scan all incoming items
for (const item of items) {
  const j = item.json || {};

  // servers usually come from webhook body
  if (j.body?.dev_server) devServer = j.body.dev_server;
  if (j.body?.prod_server) prodServer = j.body.prod_server;

  // databases come from SQL nodes
  if (j.name && j.type === 'dev') devDatabases.push(j.name);
  if (j.name && j.type === 'prod') prodDatabases.push(j.name);
}

return [{
  json: {
    dev_server: devServer,
    prod_server: prodServer,
    dev_databases: devDatabases,
    prod_databases: prodDatabases
  }
}];
